// Сервер локальной сети для «Плохие парни». Без зависимостей: нужен только Node.js (nodejs.org).
// Запуск:  node server.js   (рядом должен лежать zacepery.html)
const http = require('http'), fs = require('fs'), path = require('path'), crypto = require('crypto'), os = require('os');
const PORT = +process.env.PORT || 8080, MAX = 5;
const GAME = Buffer.from('', 'base64');
// если рядом лежит свежий zacepery.html, берём его, иначе встроенную версию
const page = () => { const p = path.join(__dirname, 'zacepery.html'); return fs.existsSync(p) ? fs.readFileSync(p) : GAME; };
const server = http.createServer((req, res) => {
  if (req.url === '/zc-ping') { res.end('zc'); return; }
  const h = page();
  if (!h) { res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' }); res.end('Положи zacepery.html рядом с server.js'); return; }
  res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' }); res.end(h);
});
const clients = new Set(), rooms = new Map(); let uid = 0, rid = 0;
server.on('upgrade', (req, sock) => {
  if (req.url !== '/ws') { sock.destroy(); return; }
  const acc = crypto.createHash('sha1').update(req.headers['sec-websocket-key'] + '258EAFA5-E914-47DA-95CA-C5AB0DC85B11').digest('base64');
  sock.write('HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: ' + acc + '\r\n\r\n');
  sock.setNoDelay(true);
  const c = { sock, id: 'p' + (++uid), room: null, buf: Buffer.alloc(0) }; clients.add(c);
  sock.on('data', d => {
    c.buf = Buffer.concat([c.buf, d]);
    for (;;) { const f = parse(c); if (!f) break; if (f.op === 8) { sock.end(); return; } if (f.op === 1) handle(c, f.txt); }
  });
  sock.on('close', () => drop(c)); sock.on('error', () => drop(c));
  wsend(c, { t: 'rooms', rooms: roomList() });
});
function parse(c) {
  const b = c.buf; if (b.length < 2) return null;
  const op = b[0] & 15; let len = b[1] & 127, off = 2;
  if (len === 126) { if (b.length < 4) return null; len = b.readUInt16BE(2); off = 4; }
  else if (len === 127) { if (b.length < 10) return null; len = Number(b.readBigUInt64BE(2)); off = 10; }
  const masked = (b[1] & 128) !== 0; let mask = null;
  if (masked) { if (b.length < off + 4) return null; mask = b.slice(off, off + 4); off += 4; }
  if (b.length < off + len) return null;
  const data = Buffer.from(b.slice(off, off + len));
  if (mask) for (let i = 0; i < len; i++) data[i] ^= mask[i & 3];
  c.buf = b.slice(off + len);
  return { op, txt: data.toString('utf8') };
}
function wsend(c, obj) {
  const p = Buffer.from(JSON.stringify(obj)), n = p.length; let h;
  if (n < 126) h = Buffer.from([0x81, n]);
  else if (n < 65536) { h = Buffer.alloc(4); h[0] = 0x81; h[1] = 126; h.writeUInt16BE(n, 2); }
  else { h = Buffer.alloc(10); h[0] = 0x81; h[1] = 127; h.writeBigUInt64BE(BigInt(n), 2); }
  try { c.sock.write(Buffer.concat([h, p])); } catch (e) {}
}
const roomList = () => [...rooms.values()].map(r => ({ id: r.id, name: r.name, n: r.members.size, max: MAX }));
const bcastRooms = () => clients.forEach(c => { if (!c.room) wsend(c, { t: 'rooms', rooms: roomList() }); });
function handle(c, txt) {
  let m; try { m = JSON.parse(txt); } catch (e) { return; }
  if (m.t === 'list') return wsend(c, { t: 'rooms', rooms: roomList() });
  if (m.t === 'create') {
    if (c.room) return;
    const r = { id: 'r' + (++rid), host: c.id, name: String(m.name || 'Комната').slice(0, 20), members: new Set([c]) };
    rooms.set(r.id, r); c.room = r;
    wsend(c, { t: 'joined', role: 'h', pid: c.id, room: r.id, peers: [] }); bcastRooms(); return;
  }
  if (m.t === 'join') {
    if (c.room) return;
    const r = rooms.get(m.id); if (!r) return wsend(c, { t: 'err', e: 'gone' });
    if (r.members.size >= MAX) return wsend(c, { t: 'err', e: 'full' });
    const peers = [...r.members].map(x => x.id);
    r.members.add(c); c.room = r;
    wsend(c, { t: 'joined', role: 'g', pid: c.id, room: r.id, peers, host: r.host });
    r.members.forEach(x => { if (x !== c) wsend(x, { t: 'peer+', pid: c.id }); });
    bcastRooms(); return;
  }
  if (m.t === 'msg' && c.room) { c.room.members.forEach(x => { if (x !== c) wsend(x, { t: 'msg', from: c.id, d: m.d }); }); return; }
  if (m.t === 'leave') leave(c);
}
function leave(c) {
  const r = c.room; if (!r) return;
  c.room = null; r.members.delete(c);
  if (r.host === c.id) { r.members.forEach(x => { x.room = null; wsend(x, { t: 'closed' }); }); rooms.delete(r.id); }
  else r.members.forEach(x => wsend(x, { t: 'peer-', pid: c.id }));
  bcastRooms();
}
function drop(c) { if (!clients.has(c)) return; clients.delete(c); leave(c); }
setInterval(bcastRooms, 2000);
server.listen(PORT, '0.0.0.0', () => {
  const ips = [];
  for (const l of Object.values(os.networkInterfaces())) for (const i of l) if (i.family === 'IPv4' && !i.internal) ips.push(i.address);
  ips.sort((a, b) => (/^(192\.168|10\.|172\.(1[6-9]|2\d|3[01]))/.test(b) ? 1 : 0) - (/^(192\.168|10\.|172\.(1[6-9]|2\d|3[01]))/.test(a) ? 1 : 0));
  console.log('\n==============================================');
  console.log('  ИГРА «ПЛОХИЕ ПАРНИ»: СЕРВЕР ЗАПУЩЕН');
  console.log('==============================================\n');
  if (process.env.PORT && !process.env.LOCAL) { console.log('Работает на хостинге. Адрес игры смотри в панели хостинга.\n'); return; }
  console.log('1) На этом компьютере игра сейчас откроется сама.');
  console.log('   Если не открылась, зайди на: http://localhost:' + PORT + '\n');
  console.log('2) ДРУЗЬЯМ в твоём Wi-Fi отправь этот адрес (открывать в браузере телефона):\n');
  ips.forEach(a => console.log('       http://' + a + ':' + PORT));
  console.log('\n3) В игре: Меню → Мультиплеер. Один нажимает «Создать комнату»,');
  console.log('   остальные видят её в списке и нажимают на неё. До ' + MAX + ' игроков.\n');
  console.log('Если Windows спросит про доступ в сеть, нажми «Разрешить».');
  console.log('Не закрывай это окно, пока играете. Чтобы остановить: закрой окно.\n');
  try { const { exec } = require('child_process'); const u = 'http://localhost:' + PORT; exec(process.platform === 'win32' ? 'start "" ' + u : process.platform === 'darwin' ? 'open ' + u : 'xdg-open ' + u, () => {}); } catch (e) {}
});
